// The tables of units, as generated by scripts/lu-communes.mjs (which checks every row's totals
// against the sum of its units, and `--check` that the files are what the official tables give),
// against values read in the official tables by hand.
import { describe, expect, it } from 'vitest';
import { communeByName, communesFor, foldName, luParamsFor, slugOf } from '../src/index.js';

describe('the tables of units', () => {
  it('79 communes each year, in the table’s order, each once', () => {
    for (const year of [2025, 2026]) {
      const names = communesFor(year).value.map((x) => x.name);
      expect(names).toHaveLength(79);
      expect(new Set(names).size).toBe(79);
      expect(names[0]).toBe('Adligenswil');
      expect(names.at(-1)).toBe('Zell');
    }
  });

  it('the state’s units: 1.55 in 2025, 1.45 in 2026; Christ Catholic 0.31 both years', () => {
    // lu-2025-communal-steuereinheiten p. 1, lu-2026-communal-steuereinheiten p. 1.
    expect(luParamsFor(2025).stateUnits.value).toBe(15_500);
    expect(luParamsFor(2026).stateUnits.value).toBe(14_500);
    expect(luParamsFor(2025).christCatholicUnits.value).toBe(3_100);
    expect(luParamsFor(2026).christCatholicUnits.value).toBe(3_100);
  });

  // [year, commune, Einwohnergemeinde, römisch-katholisch (parish), evangelisch-reformiert (parish)]
  const ROWS: [number, string, number, number, string | null, number, string][] = [
    [2025, 'Luzern', 15_500, 2_500, null, 2_500, 'Luzern'],
    [2026, 'Luzern', 14_500, 2_300, null, 2_500, 'Luzern'],
    [2025, 'Kriens', 19_000, 2_500, null, 2_500, 'Luzern'],
    [2026, 'Kriens', 18_500, 2_500, null, 2_500, 'Luzern'],
    [2025, 'Emmen', 21_500, 2_850, null, 2_500, 'Luzern'],
    [2026, 'Horw', 14_000, 2_500, null, 2_500, 'Horw'],
    [2025, 'Buchrain', 19_500, 2_565, null, 2_500, 'Luzern'],
    [2026, 'Meggen', 9_000, 1_445, null, 2_500, 'Meggen-Adligenswil-Udligenswil'],
    [2026, 'Inwil', 16_000, 2_160, null, 2_200, 'Hochdorf'],
    [2025, 'Dierikon', 18_500, 2_100, 'Root', 2_500, 'Luzern'],
    [2026, 'Pfaffnau', 23_000, 4_000, null, 2_650, 'Reiden'],
  ];
  it.each(ROWS)('%i %s', (year, name, units, rk, rkParish, er, erParish) => {
    const x = communeByName(year, name);
    expect(x).toEqual({
      name,
      units,
      catholic: { units: rk, parish: rkParish },
      reformed: { units: er, parish: erParish },
    });
  });

  it('the totals the tables print (inkl. Staats-, Gemeinde- und Kirche)', () => {
    // lu-2025-communal-steuereinheiten p. 1: Luzern 3.35 / 3.35 / 3.41 / 3.10; Emmen 3.985.
    // lu-2026-communal-steuereinheiten p. 1: Luzern 3.13 / 3.15 / 3.21 / 2.90.
    const total = (year: number, name: string, church: number) =>
      luParamsFor(year).stateUnits.value + communeByName(year, name)!.units + church;
    const lu25 = communeByName(2025, 'Luzern')!;
    expect(total(2025, 'Luzern', lu25.catholic.units)).toBe(33_500);
    expect(total(2025, 'Luzern', 3_100)).toBe(34_100);
    expect(total(2025, 'Luzern', 0)).toBe(31_000);
    expect(total(2025, 'Emmen', communeByName(2025, 'Emmen')!.catholic.units)).toBe(39_850);
    const lu26 = communeByName(2026, 'Luzern')!;
    expect(total(2026, 'Luzern', lu26.catholic.units)).toBe(31_300);
    expect(total(2026, 'Luzern', lu26.reformed.units)).toBe(31_500);
    expect(total(2026, 'Luzern', 0)).toBe(29_000);
  });

  it('a commune by its name or slug, accents and case aside; none outside the table', () => {
    expect(communeByName(2025, 'romerswil')?.name).toBe('Römerswil');
    expect(communeByName(2026, 'escholzmatt-marbach')?.name).toBe('Escholzmatt-Marbach');
    expect(slugOf('Escholzmatt-Marbach')).toBe('escholzmatt-marbach');
    expect(foldName('Büron')).toBe('buron');
    // Honau is not in the 2025 or 2026 table of units (the 2025 guide's rental value groups still
    // list it, lu-2025-guide-wegleitung p. 56).
    expect(communeByName(2025, 'Honau')).toBeUndefined();
    expect(communeByName(2026, 'Zürich')).toBeUndefined();
  });
});
